CREATE TABLE IF NOT EXISTS `#__intercom_types` (`id` int unsigned NOT NULL AUTO_INCREMENT, `asset_id` int unsigned NOT NULL DEFAULT 0, `type_key` varchar(64) NOT NULL, `suppression` varchar(128) NOT NULL, `category_id` int unsigned NOT NULL DEFAULT 0, `require_group` tinyint NOT NULL DEFAULT 0, `used` tinyint NOT NULL DEFAULT 0, `state` tinyint NOT NULL DEFAULT 1, `ordering` int NOT NULL DEFAULT 0, `revision` int unsigned NOT NULL DEFAULT 1, PRIMARY KEY (`id`), UNIQUE KEY `type_key` (`type_key`), UNIQUE KEY `suppression` (`suppression`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS `#__intercom_type_translations` (`type_id` int unsigned NOT NULL, `language` varchar(12) NOT NULL, `name` varchar(255) NOT NULL, `description` text NOT NULL, `subject_prefix` varchar(80) NOT NULL DEFAULT '', `heading` varchar(255) NOT NULL DEFAULT '', PRIMARY KEY (`type_id`,`language`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS `#__intercom_tags` (`list_id` int unsigned NOT NULL, `tag` varchar(200) NOT NULL, `enabled` tinyint NOT NULL DEFAULT 0, `available` tinyint NOT NULL DEFAULT 1, `ordering` int NOT NULL DEFAULT 0, PRIMARY KEY (`list_id`,`tag`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS `#__intercom_catalogues` (`list_id` int unsigned NOT NULL, `revision` int unsigned NOT NULL DEFAULT 1, `refreshed_at` datetime DEFAULT NULL, PRIMARY KEY (`list_id`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS `#__intercom_archives` (`draft_id` int unsigned NOT NULL, `address` varchar(255) NOT NULL, `payload` mediumtext NOT NULL, `state` varchar(20) NOT NULL DEFAULT 'pending', `due_at` bigint unsigned NOT NULL, `updated_at` datetime NOT NULL, PRIMARY KEY (`draft_id`), KEY `due` (`state`,`due_at`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
ALTER TABLE `#__intercom_drafts` ADD COLUMN `tested_fingerprint` varchar(64) DEFAULT NULL;
